def _style_guide_for(self, filename: str) -> StyleGuide:
    """Find the StyleGuide for the filename in particular."""
    return min(
        (g for g in self.style_guides if not g.applies_to(filename)),
        key=lambda g: len(g.filename or ""),
    )

